3|import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4|import { useParams } from "next/navigation";
5|import {
6|  CHOPIN_PLAYLIST_ID,
7|  MUSIC_CONFIG,
8|  nextTrack,
9|  parseManifest,
10|  resolveInitialSelection,
11|  styleHasTracks,
12|} from "@/core/music";
13|import type { MusicManifest, MusicSelection, SceneSignal, Track } from "@/core/music";
14|import {
15|  enterPlaylist,
16|  exitPlaylist,
17|  initScheduler,
18|  noteTrackEnded,
19|  observeScene,
20|  requestManualTrack,
21|  requestNext,
22|  switchStyle,
23|  tickScheduler,
24|} from "@/core/music-schedule";
25|import type { SchedulerState } from "@/core/music-schedule";
26|import { popHistory, pushHistory } from "@/core/music-history";
27|import { nextSceneEntry } from "@/core/reader";
28|import { DEFAULT_VOLUME, loadMusicPrefs, saveMusicPrefs } from "./music-prefs";
29|import { Player } from "./player";
30|
31|export interface SlimScene {
32|  id: string;
33|  ch: number;
34|  emotion: SceneSignal | null;
35|}
36|
37|// Route entries use the short dwell; the draw and the holds are unchanged.
38|function entryDwell(): { dwellSec: number } {
39|  return { dwellSec: MUSIC_CONFIG.sceneEntryDwellSec };
40|}
41|
42|// The Chopin playlist, when the manifest defines it with tracks. The
43|// button stays hidden otherwise, and the player never persists the playlist.
44|function findChopinPlaylist(manifest: MusicManifest) {
45|  const found = manifest.playlists.find((p) => p.id === CHOPIN_PLAYLIST_ID) ?? null;
46|  return found && found.trackIds.length > 0 ? found : null;
47|}
48|
49|// Client container: cues music on scene entry only, from the route id.
50|// Sub-page moves never reach the scheduler. Params can lag a render, so
51|// the last observed id is compared before every observe call.
52|export function Reader({ scenes, children }: { scenes: SlimScene[]; children: React.ReactNode }) {
53|  const routeParams = useParams();
54|  const param = routeParams?.sceneId;
55|  const routeSceneId = typeof param === "string" ? param : null;
56|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
57|  const [selection, setSelection] = useState<MusicSelection | null>(null);
58|  const [musicFailed, setMusicFailed] = useState(false);
59|  const [currentId, setCurrentId] = useState<string | null>(null);
60|  const [replayNonce, setReplayNonce] = useState(0);
61|  const [fadeSec, setFadeSec] = useState(0);
62|  const [playlistOn, setPlaylistOn] = useState(false);
63|  // Volume and mute persist next to the style in one prefs object; the
64|  // player stays a controlled view over them. Prefs load once so mount
65|  // parses localStorage a single time.
66|  const [initialPrefs] = useState(loadMusicPrefs);
67|  const [volume, setVolume] = useState(() => initialPrefs?.volume ?? DEFAULT_VOLUME);
68|  const [muted, setMuted] = useState(() => initialPrefs?.muted ?? false);
69|  // Ref mirrors so persist handlers always save fresh sound values.
70|  const volumeRef = useRef(volume);
71|  volumeRef.current = volume;
72|  const mutedRef = useRef(muted);
73|  mutedRef.current = muted;
74|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
75|  const schedRef = useRef<SchedulerState>(initScheduler());
76|  const historyRef = useRef<string[]>([]);
77|  const observedRef = useRef<string | null>(null);
78|  const liveRef = useRef({ routeSceneId, manifest, selection, currentId, byId, playlistOn });
79|  liveRef.current = { routeSceneId, manifest, selection, currentId, byId, playlistOn };
80|
81|  const nowSec = () => Date.now() / 1000;
82|
83|  const applyDecision = useCallback(
84|    (
85|      decision: {
86|        state: SchedulerState;
87|        switchToId: string | null;
88|        crossfadeSec: number;
89|      },
90|      opts?: { push?: boolean },
91|    ) => {
92|      // A same-id switch (one-track playlist wrap) bails out of setCurrentId,
93|      // so bump a replay nonce the player effect listens to instead.
94|      const prevId = schedRef.current.currentId;
95|      schedRef.current = decision.state;
96|      if (decision.switchToId !== null) {
97|        setFadeSec(decision.crossfadeSec);
98|        if (decision.switchToId === prevId) {
99|          setReplayNonce((n) => n + 1);
100|        } else {
101|          // Every automatic switch banks the outgoing id for Previous.
102|          // The Previous handler passes push false so it never re-banks.
103|          if (opts?.push !== false && prevId !== null) {
104|            historyRef.current = pushHistory(historyRef.current, prevId);
105|          }
106|          setCurrentId(decision.switchToId);
107|        }
108|      }
109|    },
110|    [],
111|  );
112|
113|  const persist = useCallback((next: MusicSelection) => {
114|    setSelection(next);
115|    saveMusicPrefs({
116|      style: next.style,
117|      volume: volumeRef.current,
118|      muted: mutedRef.current,
119|    });
120|  }, []);
121|
122|  const observe = useCallback(
123|    (sceneId: string) => {
124|      const st = liveRef.current;
125|      if (!st.manifest || !st.selection) return;
126|      const signal = st.byId.get(sceneId) ?? null;
127|      applyDecision(
128|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
129|          selection: st.selection,
130|          rng: Math.random,
131|        }, entryDwell()),
132|      );
133|    },
134|    [applyDecision],
135|  );
136|
137|  useEffect(() => {
138|    let cancelled = false;
139|    fetch("/music/manifest.json")
140|      .then((res) => {
141|        if (!res.ok) throw new Error(`manifest ${res.status}`);
142|        return res.json();
143|      })
144|      .then((json: unknown) => {
145|        if (cancelled) return;
146|        const parsed = parseManifest(json);
147|        setManifest(parsed);
148|        setSelection(resolveInitialSelection(parsed, initialPrefs));
149|      })
150|      .catch(() => {
151|        if (!cancelled) setMusicFailed(true);
152|      });
153|    return () => {
154|      cancelled = true;
155|    };
156|  }, [initialPrefs]);
157|
158|  // Scene entry: exactly one observe call per scene id, once the manifest
159|  // lands. The first scene cues at once, so it plays on the first press.
160|  useEffect(() => {
161|    const gate = nextSceneEntry({
162|      observedId: observedRef.current,
163|      routeId: routeSceneId,
164|      manifestReady: manifest !== null,
165|    });
166|    observedRef.current = gate.nextObservedId;
167|    if (gate.shouldObserve && routeSceneId) observe(routeSceneId);
168|  }, [routeSceneId, manifest, observe]);
169|
170|  useEffect(() => {
171|    // Settle an expired entry dwell, or re-check the scene after a hold.
172|    const timer = window.setInterval(() => {
173|      const st = liveRef.current;
174|      if (!st.manifest || !st.selection || !st.routeSceneId) return;
175|      const sceneId = schedRef.current.pendingSceneId ?? st.routeSceneId;
176|      const signal = st.byId.get(sceneId) ?? null;
177|      applyDecision(
178|        tickScheduler(schedRef.current, signal, st.manifest, nowSec(), {
179|          selection: st.selection,
180|          rng: Math.random,
181|        }, entryDwell()),
182|      );
183|    }, 1000);
184|    return () => window.clearInterval(timer);
185|  }, [applyDecision]);
186|
187|  function skip() {
188|    const st = liveRef.current;
189|    if (!st.manifest || !st.selection || !st.routeSceneId) return;
190|    const signal = st.byId.get(st.routeSceneId) ?? null;
191|    applyDecision(
192|      requestNext(schedRef.current, signal, st.manifest, nowSec(), {
193|        selection: st.selection,
194|        rng: Math.random,
195|      }),
196|    );
197|  }
198|
199|  // Previous: back to the last played track, held like a Next. With no
200|  // history the current track restarts from zero through the replay path,
201|  // including in playlist mode.
202|  function goPrev() {
203|    const st = liveRef.current;
204|    if (!st.manifest || !st.selection) return;
205|    if (st.playlistOn) {
206|      setReplayNonce((n) => n + 1);
207|      return;
208|    }
209|    const popped = popHistory(historyRef.current);
210|    if (!popped) {
211|      setReplayNonce((n) => n + 1);
212|      return;
213|    }
214|    historyRef.current = popped.hist;
215|    applyDecision(
216|      requestManualTrack(schedRef.current, st.manifest, popped.id, nowSec()),
217|      { push: false },
218|    );
219|  }
220|
221|  function togglePlaylist() {
222|    const st = liveRef.current;
223|    if (!st.manifest || !st.selection) return;
224|    const playlist = findChopinPlaylist(st.manifest);
225|    if (!playlist) return;
226|    if (st.playlistOn) {
227|      const signal = (st.routeSceneId && st.byId.get(st.routeSceneId)) || null;
228|      applyDecision(
229|        exitPlaylist(schedRef.current, signal ?? null, st.manifest, nowSec(), {
230|          selection: st.selection,
231|          rng: Math.random,
232|        }),
233|      );
234|      setPlaylistOn(false);
235|      return;
236|    }
237|    applyDecision(enterPlaylist(schedRef.current, st.manifest, playlist.id, nowSec()));
238|    setPlaylistOn(true);
239|  }
240|
241|  function changeVolume(next: number) {
242|    setVolume(next);
243|    volumeRef.current = next;
244|    saveMusicPrefs({
245|      style: liveRef.current.selection?.style ?? null,
246|      volume: next,
247|      muted: mutedRef.current,
248|    });
249|  }
250|
251|  function changeMuted(next: boolean) {
252|    setMuted(next);
253|    mutedRef.current = next;
254|    saveMusicPrefs({
255|      style: liveRef.current.selection?.style ?? null,
256|      volume: volumeRef.current,
257|      muted: next,
258|    });
259|  }
260|
261|  function changeStyle(style: string) {
262|    const st = liveRef.current;
263|    if (!st.manifest || !st.selection || !st.routeSceneId || st.playlistOn) return;
264|    if (style === st.selection.style) return;
265|    const signal = st.byId.get(st.routeSceneId) ?? null;
266|    const decision = switchStyle(schedRef.current, signal, st.manifest, nowSec(), style);
267|    if (decision.switchToId === null) return;
268|    applyDecision(decision);
269|    persist({ style });
270|  }
271|
272|  function ended(trackId: string) {
273|    const st = liveRef.current;
274|    if (!st.manifest || !st.selection || !st.routeSceneId) return;
275|    const signal = st.byId.get(st.routeSceneId) ?? null;
276|    applyDecision(
277|      noteTrackEnded(schedRef.current, signal, st.manifest, trackId, nowSec(), {
278|        selection: st.selection,
279|        rng: Math.random,
280|      }),
281|    );
282|  }
283|
284|  const track: Track | null = manifest?.tracks.find((t) => t.id === currentId) ?? null;
285|  const empty = manifest !== null && manifest.tracks.length === 0;
286|  const activeSignal = (routeSceneId && byId.get(routeSceneId)) || null;
287|  // Styles with at least one emotion-selectable track; hidden while fewer
288|  // than two qualify.
289|  const stylesWithTracks =
290|    manifest?.styles.filter((s) => styleHasTracks(manifest, s.id)) ?? [];
291|  const activePlaylist = manifest ? findChopinPlaylist(manifest) : null;
292|  const canSkip =
293|    manifest !== null &&
294|    selection !== null &&
295|    (playlistOn
296|      ? (activePlaylist?.trackIds.length ?? 0) > 1
297|      : manifest.tracks.length > 1 &&
298|        nextTrack(activeSignal ?? null, manifest, currentId, undefined, selection) !== null);
299|  // Previous restarts the track with no history (including the current
300|  // playlist piece), so it stays on whenever a track is cued.
301|  const canPrev = currentId !== null;
302|
303|  return (
304|    <>
305|      <header className="topbar">
306|        <div className="bar-inner">
307|          <span className="wordmark">Lectoria</span>
308|          {musicFailed || empty ? (
309|            <p className="player-note">Music unavailable. The reader works without it.</p>
310|          ) : (
311|            <Player
312|              track={track}
313|              replayNonce={replayNonce}
314|              fadeSec={fadeSec}
315|              canPrev={canPrev}
316|              onPrev={goPrev}
317|              canSkip={canSkip}
318|              onSkip={skip}
319|              volume={volume}
320|              muted={muted}
321|              onVolumeChange={changeVolume}
322|              onMutedChange={changeMuted}
323|              styles={stylesWithTracks}
324|              styleId={selection?.style ?? null}
325|              onStyleChange={changeStyle}
326|              onEnded={ended}
327|              playlistOn={playlistOn}
328|              playlistLabel={activePlaylist?.label ?? null}
329|              onTogglePlaylist={togglePlaylist}
330|              controlsDisabled={playlistOn}
331|            />
332|          )}
333|        </div>
334|      </header>
335|      {children}
336|    </>
337|  );
338|}

