274|    if (!st.manifest || !st.selection || !st.routeSceneId) return;
275|    const signal = st.byId.get(st.routeSceneId) ?? null;
276|    applyDecision(
277|      noteTrackEnded(schedRef.current, signal, st.manifest, trackId, nowSec(), {
278|        selection: st.selection,
279|        rng: Math.random,
280|      }),
281|    );
282|  }
283|
284|  const track: Track | null = manifest?.tracks.find((t) => t.id === currentId) ?? null;
285|  const empty = manifest !== null && manifest.tracks.length === 0;
286|  const activeSignal = (routeSceneId && byId.get(routeSceneId)) || null;
287|  // Styles with at least one emotion-selectable track; hidden while fewer
288|  // than two qualify.
289|  const stylesWithTracks =
290|    manifest?.styles.filter((s) => styleHasTracks(manifest, s.id)) ?? [];
291|  const activePlaylist = manifest ? findChopinPlaylist(manifest) : null;
292|  const canSkip =
293|    manifest !== null &&
294|    selection !== null &&
295|    (playlistOn
296|      ? (activePlaylist?.trackIds.length ?? 0) > 1
297|      : manifest.tracks.length > 1 &&
298|        nextTrack(activeSignal ?? null, manifest, currentId, undefined, selection) !== null);
299|  // Previous restarts the track with no history (including the current
300|  // playlist piece), so it stays on whenever a track is cued.
301|  const canPrev = currentId !== null;
302|
303|  return (
304|    <>
305|      <header className="topbar">
306|        <div className="bar-inner">
307|          <span className="wordmark">Lectoria</span>
308|          {musicFailed || empty ? (
309|            <p className="player-note">Music unavailable. The reader works without it.</p>
310|          ) : (
311|            <Player
312|              track={track}
313|              replayNonce={replayNonce}
314|              fadeSec={fadeSec}
315|              canPrev={canPrev}
316|              onPrev={goPrev}
317|              canSkip={canSkip}
318|              onSkip={skip}
319|              volume={volume}
320|              muted={muted}
321|              onVolumeChange={changeVolume}
322|              onMutedChange={changeMuted}
323|              styles={stylesWithTracks}
324|              styleId={selection?.style ?? null}
325|              onStyleChange={changeStyle}
326|              onEnded={ended}
327|              playlistOn={playlistOn}
328|              playlistLabel={activePlaylist?.label ?? null}
329|              onTogglePlaylist={togglePlaylist}
330|              controlsDisabled={playlistOn}
331|            />
332|          )}
333|        </div>
334|      </header>
